// === NAME - DESCRIPTION: Function or Not - decide whether each relation (table, set of pairs, or graph description) is a function ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$type = rand(0,2);

// Build a relation that is NOT a function: one input with two outputs
$inA = rand(1,6);
$outA = rand(1,9);
$outB = $outA + randfrom(array(1,2,3,4,5));
if ($outB > 12) { $outB = $outA - randfrom(array(1,2,3,4,5)); }
if ($outB < 0) { $outB = $outA + 1; }

// Build a relation that IS a function: distinct inputs
$in1 = rand(1,4);
$in2 = $in1 + rand(1,2);
$in3 = $in2 + rand(1,2);
$f1 = rand(1,9);
$f2 = rand(1,9);
$f3 = rand(1,9);

// Part (a): a table that is NOT a function
$questions[0] = array(
  "The table below pairs each input with an output. Is the relationship a function?",
  "Yes, it is a function",
  "No, it is not a function"
);
$answer[0] = 1;

// Part (b): a set of ordered pairs that IS a function
$questions[1] = array(
  "The set of ordered pairs is given. Is the relationship a function?",
  "Yes, it is a function",
  "No, it is not a function"
);
$answer[1] = 0;

// Part (c): a set of ordered pairs that is NOT a function
$questions[2] = array(
  "The set of ordered pairs is given. Is the relationship a function?",
  "Yes, it is a function",
  "No, it is not a function"
);
$answer[2] = 1;

$anstypes = "choices,choices,choices";

// === QUESTION TEXT ===
<p>A <strong>function</strong> is a relationship in which each input is paired with exactly one output. Decide whether each relationship below is a function.</p>

<p><strong>(a)</strong> The table below pairs each input with an output. Is the relationship a function?</p>
<table border="1" cellpadding="6" cellspacing="0">
<tr><th>Input</th><th>Output</th></tr>
<tr><td>`$inA`</td><td>`$outA`</td></tr>
<tr><td>`$inA`</td><td>`$outB`</td></tr>
<tr><td>`$in2`</td><td>`$f2`</td></tr>
</table>
<p>$answerbox[0]</p>

<p><strong>(b)</strong> The set of ordered pairs is given. Is the relationship a function?</p>
<p>`{($in1, $f1), ($in2, $f2), ($in3, $f3)}`</p>
<p>$answerbox[1]</p>

<p><strong>(c)</strong> The set of ordered pairs is given. Is the relationship a function?</p>
<p>`{($in1, $f1), ($in2, $f2), ($in1, $f3)}`</p>
<p>$answerbox[2]</p>

// === ANSWER ===
$solutionguide = '<p>A relationship is a function when no input is repeated with two different outputs.</p>
<p><strong>Step 1 &mdash; Check part (a).</strong> The input ' . $inA . ' appears twice, paired with ' . $outA . ' and with ' . $outB . '. One input has two outputs, so this table is <strong>not</strong> a function.</p>
<p><strong>Step 2 &mdash; Check part (b).</strong> The inputs are ' . $in1 . ', ' . $in2 . ', and ' . $in3 . '. They are all different, so each input has exactly one output. This set <strong>is</strong> a function.</p>
<p><strong>Step 3 &mdash; Check part (c).</strong> The input ' . $in1 . ' appears twice, paired with ' . $f1 . ' and with ' . $f3 . '. One input has two outputs, so this set is <strong>not</strong> a function.</p>
<p><strong>Answer:</strong> (a) No, it is not a function; (b) Yes, it is a function; (c) No, it is not a function.</p>';

