// Two-variable LP: maximize P = p1*x + p2*y subject to resource constraints.
// Built so the optimum is at the intersection of the two binding constraints,
// with integer coordinates, and all slack variables nonnegative integers.

// Choose the optimal mix first, then build constraints that bind there.
$xopt = rand(3,9);
$yopt = rand(3,9);

// Resource usage per unit (small, distinct)
$a1 = rand(2,5);   // resource 1 per x
$b1 = rand(2,5);   // resource 1 per y
$a2 = rand(2,5);   // resource 2 per x
$b2 = rand(2,5);   // resource 2 per y

// Ensure the two constraint lines are not parallel and the system is well-conditioned
while (($a1*$b2 - $a2*$b1) == 0) {
  $b2 = rand(2,5);
}

// Right-hand sides so that (xopt, yopt) is exactly on both lines
$c1 = $a1*$xopt + $b1*$yopt;
$c2 = $a2*$xopt + $b2*$yopt;

// Profits per unit: positive integers, distinct, and the optimum must beat
// the axis intercepts so the intersection really is optimal.
$p1 = rand(4,9);
$p2 = rand(4,9);
while ($p1 == $p2) {
  $p2 = rand(4,9);
}

$Popt = $p1*$xopt + $p2*$yopt;

// Intercepts of constraint 1
$Px1 = $p1 * ($c1/$a1);
$Py1 = $p2 * ($c1/$b1);
// Intercepts of constraint 2
$Px2 = $p1 * ($c2/$a2);
$Py2 = $p2 * ($c2/$b2);

// Regenerate profits until the intersection strictly beats all axis vertices
$tries = 0;
while (($Popt <= $Px1 + 0.0001 || $Popt <= $Py1 + 0.0001 || $Popt <= $Px2 + 0.0001 || $Popt <= $Py2 + 0.0001) && $tries < 200) {
