  $Popt = $p1*$xopt + $p2*$yopt;
  $Px1 = $p1 * ($c1/$a1);
  $Py1 = $p2 * ($c1/$b1);
  $Px2 = $p1 * ($c2/$a2);
  $Py2 = $p2 * ($c2/$b2);
  $tries = $tries + 1;
}

