// === NAME - DESCRIPTION: Matrix Inverse & Equation (3x3) - Find A^{-1} then solve AX=B using the inverse method ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Build a 3x3 matrix A with a guaranteed nonzero determinant, then solve AX=B via A^{-1}.
// Entries are small integers so the inverse is exact and the arithmetic is checkable by hand.

// Pick a diagonal-dominant-ish integer matrix, retry until det is comfortably nonzero.
$det = 0;
$tries = 0;
while (($det == 0 || abs($det) < 2) && $tries < 200) {
  $tries = $tries + 1;
  $a11 = rand(-3,3); $a12 = rand(-3,3); $a13 = rand(-3,3);
  $a21 = rand(-3,3); $a22 = rand(-3,3); $a23 = rand(-3,3);
  $a31 = rand(-3,3); $a32 = rand(-3,3); $a33 = rand(-3,3);
  // determinant by cofactor expansion along the first row
  $det = $a11*($a22*$a33 - $a23*$a32) - $a12*($a21*$a33 - $a23*$a31) + $a13*($a21*$a32 - $a22*$a31);
}

// Cofactor matrix entries
$c11 =  ($a22*$a33 - $a23*$a32);
$c12 = -($a21*$a33 - $a23*$a31);
$c13 =  ($a21*$a32 - $a22*$a31);
$c21 = -($a12*$a33 - $a13*$a32);
$c22 =  ($a11*$a33 - $a13*$a31);
$c23 = -($a11*$a32 - $a12*$a31);
$c31 =  ($a12*$a23 - $a13*$a22);
$c32 = -($a11*$a23 - $a13*$a21);
$c33 =  ($a11*$a22 - $a12*$a21);

// Adjugate = transpose of cofactor matrix; A^{-1} = adj/det
$i11 = $c11; $i12 = $c21; $i13 = $c31;
$i21 = $c12; $i22 = $c22; $i23 = $c32;
$i31 = $c13; $i32 = $c23; $i33 = $c33;

// Right-hand side B: choose integer solution X first, then B = A X so the answer is exact.
$x1 = rand(-4,4); $x2 = rand(-4,4); $x3 = rand(-4,4);
$b1 = $a11*$x1 + $a12*$x2 + $a13*$x3;
$b2 = $a21*$x1 + $a22*$x2 + $a23*$x3;
$b3 = $a31*$x1 + $a32*$x2 + $a33*$x3;

// Display strings for the prompt
$Amat = "[[$a11,$a12,$a13],[$a21,$a22,$a23],[$a31,$a32,$a33]]";
$Bvec = "[[$b1],[$b2],[$b3]]";

// Part 0: the inverse matrix (exact rational entries, det divides each adjugate entry)
$answer[0] = "[[$i11/$det,$i12/$det,$i13/$det],[$i21/$det,$i22/$det,$i23/$det],[$i31/$det,$i32/$det,$i33/$det]]";
// Part 1: the solution vector X = A^{-1} B
$answer[1] = "[[$x1],[$x2],[$x3]]";

$anstypes = "calcmatrix,calcmatrix";
