 . '<p>`X = ' . $answer[0] . ' ' . $Bvec . ' = ' . $answer[1] . '`</p>'
 . '<p><strong>Answer:</strong> `A^{-1} = ' . $answer[0] . '` and `X = ' . $answer[1] . '`.</p>';

