// === NAME - DESCRIPTION: Boxplot - IQR, Fences, and Outlier Check (Context): given a five-number summary in context, compute the IQR and the 1.5*IQR fences, then decide whether a new observation is an outlier ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$contexts = array(
  array("daily screen time in minutes for a group of students", "minutes", 5),
  array("wait times in minutes at a clinic", "minutes", 2),
  array("weekly grocery spending in dollars for a group of households", "dollars", 10),
  array("scores on a quiz out of 100", "points", 4),
  array("weights in grams of a sample of apples", "grams", 5)
);
$ci = rand(0,4);
$ctx = $contexts[$ci][0];
$unit = $contexts[$ci][1];
$step = $contexts[$ci][2];

$min = $step * rand(4,10);
$q1  = $min + $step * rand(3,6);
$med = $q1 + $step * rand(2,5);
$q3  = $med + $step * rand(2,5);
$max = $q3 + $step * rand(3,6);

$iqr = $q3 - $q1;
$lowerFence = $q1 - 1.5*$iqr;
$upperFence = $q3 + 1.5*$iqr;

$isOutlier = rand(0,1);
if ($isOutlier == 1) {
  if (rand(0,1) == 1) {
    $newObs = $upperFence + $step * rand(1,4);
  } else {
    $newObs = $lowerFence - $step * rand(1,4);
  }
} else {
  $newObs = $lowerFence + $step * rand(1, max(1, floor(($upperFence - $lowerFence)/$step) - 1));
  if ($newObs <= $lowerFence) { $newObs = $lowerFence + $step; }
  if ($newObs >= $upperFence) { $newObs = $upperFence - $step; }
}

$anstypes = "number,number,number,choices";
$answer = array();
$answer[0] = $iqr;
$answer[1] = $lowerFence;
$answer[2] = $upperFence;
$questions = array();
$questions[3] = array("Yes, it is an outlier because it lies beyond a fence.", "No, it is not an outlier because it lies between the fences.", "Yes, it is an outlier because it is larger than the median.", "No, it is not an outlier because it is within one IQR of the median.");
$answer[3] = 1 - $isOutlier;
$noshuffle = "questions";

// === QUESTION TEXT ===
<p>A group of observations of $ctx is summarized by the five-number summary below.</p>
<p>Minimum = `$min` $unit, Q1 = `$q1` $unit, Median = `$med` $unit, Q3 = `$q3` $unit, Maximum = `$max` $unit.</p>
<p>(a) Find the interquartile range, IQR, in $unit.</p>
<p>IQR = $answerbox[0] $unit</p>
<p>(b) Find the lower fence, Q1 - 1.5 &middot; IQR, in $unit.</p>
<p>Lower fence = $answerbox[1] $unit</p>
<p>(c) Find the upper fence, Q3 + 1.5 &middot; IQR, in $unit.</p>
<p>Upper fence = $answerbox[2] $unit</p>
<p>(d) A new observation of `$newObs` $unit is added to the group. Using the fences, is this observation an outlier?</p>
<p>$answerbox[3]</p>

// === ANSWER ===
$solutionguide = '<p>Step 1 &mdash; Find the IQR.</p>'
 . '<p>The IQR is Q3 - Q1 = ' . $q3 . ' - ' . $q1 . ' = ' . $iqr . ' ' . $unit . '.</p>'
 . '<p>Step 2 &mdash; Find the fences.</p>'
 . '<p>Lower fence = Q1 - 1.5 &middot; IQR = ' . $q1 . ' - 1.5 &middot; ' . $iqr . ' = ' . $lowerFence . ' ' . $unit . '.</p>'
 . '<p>Upper fence = Q3 + 1.5 &middot; IQR = ' . $q3 . ' + 1.5 &middot; ' . $iqr . ' = ' . $upperFence . ' ' . $unit . '.</p>'
 . '<p>Step 3 &mdash; Check the new observation.</p>'
