// === NAME - DESCRIPTION: Select-all-that-apply on a random 8-value data set: decide which statements about the mean, median, range and mode are true ===
// === SET QUESTION TYPE TO: multans ===

// === COMMON CONTROL ===
$vals = array();
for ($i = 0; $i < 8; $i++) {
  $vals[$i] = rand(1, 20);
}
sortarray($vals);

$sum = 0;
for ($i = 0; $i < 8; $i++) {
  $sum = $sum + $vals[$i];
}
$mean = $sum / 8;
$med = ($vals[3] + $vals[4]) / 2;
$minv = $vals[0];
$maxv = $vals[7];
$rng = $maxv - $minv;

$counts = array();
for ($i = 0; $i < 8; $i++) {
  $v = $vals[$i];
  if (isset($counts[$v])) {
    $counts[$v] = $counts[$v] + 1;
  } else {
    $counts[$v] = 1;
  }
}
$maxcount = 0;
$modeval = 0;
$nmode = 0;
foreach ($counts as $v => $c) {
  if ($c > $maxcount) {
    $maxcount = $c;
    $modeval = $v;
  }
}
foreach ($counts as $v => $c) {
  if ($c == $maxcount) {
    $nmode = $nmode + 1;
  }
}
$hasmode = ($maxcount > 1);
$uniquemode = ($hasmode && $nmode == 1);

$medindata = 0;
for ($i = 0; $i < 8; $i++) {
  if ($vals[$i] == $med) { $medindata = 1; }
}
$meanwhole = (round($mean, 6) == round(round($mean), 6)) ? 1 : 0;

$stmts = array();
$truth = array();

$stmts[0] = "The mean is greater than the median.";
$truth[0] = ($mean > $med) ? 1 : 0;

$stmts[1] = "The median is one of the values in the data set.";
$truth[1] = $medindata;

$stmts[2] = "The range is greater than 10.";
$truth[2] = ($rng > 10) ? 1 : 0;

$stmts[3] = "The mean is a whole number.";
$truth[3] = $meanwhole;

$stmts[4] = "The data set has exactly one mode.";
$truth[4] = $uniquemode ? 1 : 0;

$stmts[5] = "The mean is less than the largest value in the data set.";
$truth[5] = ($mean < $maxv) ? 1 : 0;

$stmts[6] = "The median is greater than the mean.";
$truth[6] = ($med > $mean) ? 1 : 0;

$stmts[7] = "The range is the largest value minus the smallest value.";
$truth[7] = 1;

$stmts[8] = "The data set has no mode.";
$truth[8] = $hasmode ? 0 : 1;

$stmts[9] = "The mean equals the median.";
$truth[9] = (round($mean, 6) == round($med, 6)) ? 1 : 0;

$trueidx = array();
$falseidx = array();
for ($i = 0; $i < 10; $i++) {
  if ($truth[$i] == 1) { $trueidx[] = $i; } else { $falseidx[] = $i; }
}

$chosen = array();
$tpick = diffrandsfrom(0, count($trueidx) - 1, 2);
for ($k = 0; $k < 2; $k++) {
  $chosen[] = $trueidx[$tpick[$k]];
}
$fpick = diffrandsfrom(0, count($falseidx) - 1, 2);
for ($k = 0; $k < 2; $k++) {
  $chosen[] = $falseidx[$fpick[$k]];
}

$remaining = array();
for ($i = 0; $i < 10; $i++) {
  $already = 0;
  for ($k = 0; $k < count($chosen); $k++) {
    if ($chosen[$k] == $i) { $already = 1; }
  }
  if ($already == 0) { $remaining[] = $i; }
}
$rpick = diffrandsfrom(0, count($remaining) - 1, 2);
for ($k = 0; $k < 2; $k++) {
  $chosen[] = $remaining[$rpick[$k]];
}

$order = diffrandsfrom(0, 5, 6);
$questions = array();
$correctlist = array();
for ($k = 0; $k < 6; $k++) {
  $idx = $chosen[$order[$k]];
  $questions[$k] = $stmts[$idx];
  if ($truth[$idx] == 1) {
    $correctlist[] = $k;
  }
}
$answer = arraytolist($correctlist);

$valuelist = arraytolist($vals);

