  $answerline = "<p><b>Answer:</b> `IQR = $iqr` minutes, upper fence `$fenceUp`, lower fence `$fenceLo`. Because $newObs minutes lies inside the fences, it is not an outlier.</p>";
}

$solutionguide = $step1 . $step2 . $step3 . $answerline;

