// === NAME - DESCRIPTION: Probability That a Sum Is Greater Than a Value - P(Sigma x > c): find the mean and standard deviation of a sum of n observations and the probability the sum exceeds a given value ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
loadlibrary("stats");

$ctxs = array(
    array("length of", "customer service call", "customer service calls", "minutes"),
    array("weight of", "bag of coffee beans", "bags of coffee beans", "ounces"),
    array("assembly time of", "part", "parts", "seconds"),
