);
$ci = rand(0, 4);
$measure = $ctxs[$ci][0];
$item = $ctxs[$ci][1];
$itemPl = $ctxs[$ci][2];
$unit = $ctxs[$ci][3];

$mu = randfrom("8,10,12,15,20");
$sigma = randfrom("2,3,4,5,6");
$n = randfrom("16,25,36,49,64");

$muS = $n * $mu;
$sdS = $sigma * sqrt($n);

$z = randfrom("0.5,0.6,0.75,0.8,1.0,1.2,1.4");
$c = round($muS + $z * $sdS, 2);
$zexact = ($c - $muS) / $sdS;

$prob = 1 - normalcdf($c, $muS, $sdS);

$sdDisp = round($sdS, 4);
$zDisp = round($zexact, 4);
$cdfR = round(1 - $prob, 4);
$probR = round($prob, 4);

$anstypes = array("number", "number", "number");
